fn getIdFlags(cp: Codepoint) u8 {
    if (cp > 0x10FFFF) return 0;
    const block = @as(usize, cp >> 8);
    if (block >= id_stage1.len) return 0;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = id_stage1[block] + offset;
    if (stage2_idx >= id_stage2.len) return 0;
    return id_stage2[stage2_idx];
}

/// Checks if a code point has the XID_Start property
/// XID_Start characters can begin an identifier
pub fn isXidStart(cp: Codepoint) bool {
    return (getIdFlags(cp) & 1) != 0;
}

/// Checks if a code point has the XID_Continue property
/// XID_Continue characters can continue an identifier
pub fn isXidContinue(cp: Codepoint) bool {
    return (getIdFlags(cp) & 2) != 0;
}

/// Checks if a string is a valid Unicode identifier (UAX #31)
pub fn isValidIdentifier(text: []const u8) bool {
    if (text.len == 0) return false;

    var iter = std.unicode.Utf8Iterator{ .bytes = text, .i = 0 };

    // First character must be XID_Start
    const first = iter.nextCodepoint() orelse return false;
    if (!isXidStart(first)) return false;

    // Remaining characters must be XID_Continue
    while (iter.nextCodepoint()) |cp| {
        if (!isXidContinue(cp)) return false;
    }

    return true;
}
